# The one action of \Eric\memsearch-drain-weekly: drain -> recall eval -> after-run.
# Replaces the task's three separate actions (2026-10-04). On 10-01 and 10-04 the second
# action died at 02:10 with 0xC0000142 (STATUS_DLL_INIT_FAILED): the process never got far
# enough to run a line, whether it was python.exe or pwsh. It runs fine by hand and in a
# probe task while logged in, so it is a start-up failure in the overnight session, not the
# script. Running the steps from here lets a step that fails to start be retried.
param([string]$Label = 'weekly', [string]$Backends = 'memsearch,fts5,rg,jev')

$ErrorActionPreference = 'Continue'
$here = $PSScriptRoot
$pwsh = 'C:\Program Files\PowerShell\7\pwsh.exe'
$log = Join-Path $here 'logs\weekly-chain.log'
New-Item -ItemType Directory -Force (Split-Path $log) | Out-Null
function Log([string]$s) { Add-Content -LiteralPath $log -Encoding utf8 -Value "[$(Get-Date -Format s)] $s" }

$DLL_INIT_FAILED = -1073741502   # 0xC0000142 as a signed exit code

function Step([string]$name, [string[]]$argv) {
    for ($try = 1; $try -le 4; $try++) {
        & $pwsh -NoProfile -NonInteractive -File @argv
        $code = $LASTEXITCODE
        Log "$name try=$try exit=$code"
        if ($code -ne $DLL_INIT_FAILED) { return $code }
        [Threading.Thread]::Sleep(30000)
    }
    return $code
}

Log "start label=$Label"
Step 'drain' @((Join-Path $HOME '.claude\scripts\memsearch-drain.ps1')) | Out-Null
Step 'eval' @((Join-Path $here 'run-eval.ps1'), '-Label', $Label, '-Backends', $Backends) | Out-Null
# after-run checks the drain log and the ledger itself, so it always runs.
Step 'after-run' @((Join-Path $here 'after-run.ps1'), '-Label', $Label) | Out-Null
Log 'end'
----
        Log "INDEX complete - hook timeout-streak counter reset"
    }
} elseif (-not $msExe) { $Errors.Add('memsearch-exe-missing'); Log "INDEX skipped: memsearch not found" }

# --- 2c-recall. Does recall.py still open the right file? (added 2026-10-23) ---
# No model, ~1 s: the 30-case eval + the bench questions against baseline.json. Replaces the
# retired Windows weekly recall-eval chain. A drop becomes one backup error, so it reaches
# .errors.log and every session shows it at startup; nobody has to remember to run it.
$recallCheck = "$U/.claude/scripts/recall-bench/check.py"
$pyExe = @('/opt/homebrew/bin/python3', '/usr/bin/python3') | Where-Object { Test-Path $_ } | Select-Object -First 1
if ($pyExe -and (Test-Path $recallCheck)) {
    $rcOut = (& $pyExe -I $recallCheck 2>&1 | Out-String).Trim()
    Log "RECALL $rcOut"
    if ($LASTEXITCODE -ne 0) { $Errors.Add("recall-check: $rcOut") }
}

# --- 2d. Mirror the recovery guide to the cloud backup root via gws ---
if ($GwsExe -and (Test-Path "$U/.claude/RESTORE.md") -and -not $DryRun) {
    Push-Location "$U/.claude"
    try {
        $upParams = @{ fileId = $DriveRestoreId; fields = 'id,name' } | ConvertTo-Json -Compress
        $resObj = Invoke-GwsJson @('drive', 'files', 'update', '--params', $upParams, '--upload', './RESTORE.md')
        if ($resObj -and $resObj.id) { Log "RESTORE.md mirrored to _MACHINE/Backups/ (via gws)" }
    } finally {
        Pop-Location
    }
}

# --- 3. State + escalation ---
$status = if ($Errors.Count -eq 0) { 'OK' } else { 'ERROR' }
@{
    lastRun  = (Get-Date -Format 'o')
    status   = $status
    errors   = @($Errors)
    okCount  = $Results.Count
    dryRun   = [bool]$DryRun
