 (async () => {
  const b = await chromium.launch({ args: ['--no-sandbox'] });
  const p = await b.newPage({ viewport: { width: 1700, height: 1300 } });
  await p.goto(EMBED, { waitUntil: 'domcontentloaded', timeout: 90000 });
  await p.waitForSelector('.row', { timeout: 90000 });
